# -*- coding: utf-8 -*-
r"""★제안서 PPT — 이 파일만 더블클릭하십시오. (2026-09-27)

누르면 번호 세 개가 나옵니다.

    1) 제안서 PPT 만들기      54번 : 미리 써 둔 제안서 25건 중 골라 회사 서식 pptx 로
                              (27번 도면수량을 먼저 돌려 두면 그 현장 물량표가 자동으로 들어감)
    2) 점유율 80% 로 고치기   회사 제안서 pptx 의 5성급 점유율을 「해외스펙 제외 80% 이상」 으로
    3) 현장별 한 곳에 보기    흩어진 결과(산출·견적·실행·단가장·제안서·회의록)를 현장별 한 장으로
    4) 만든 제안서 점검       글자 넘침·겹침·붙음·표 밀림을 맑은 고딕 폭으로 재서 장 번호로 알려 줌
                              (1번으로 만들 때도 한 장씩 저절로 점검합니다)

AI 사용량 0. 인터넷도 쓰지 않습니다.

왜 시작.py 메뉴가 아니라 이 파일인가
    메뉴 번호는 목록 순서로 매겨져 있어(49번 = 51번 도구) 54번을 넣으면 번호가 어긋납니다.
    또 새 zip 이 자동 적용되면 도구 폴더의 파일이 옛 판으로 덮일 수 있습니다.
    이 파일은 2_KM도구 폴더 바로 아래에 있어 zip 이 건드리지 않고,
    누를 때마다 km_tools 에 54번 파일이 빠졌거나 옛 판이면 스스로 새 판을 넣습니다.
    33번 현황판에 「⑧ 현장별 한 곳에」 칸이 빠져 있으면 그것도 다시 넣습니다(원본은 .bak_54 로 남김).

제안서 내용(제안서_내용\*.json)은 없거나, 전에 드린 판 그대로일 때만 새 판으로 바꿉니다. 고쳐 쓰신 것은 덮지 않습니다.
"""
import os, sys, io, re, shutil, datetime, traceback, hashlib

PKG = 10          # 이 파일이 품은 54번 판. 파일 둘째 줄 「# 54판 vN」 과 맞춘다
SRC = {
    't54_deck.py': '# -*- coding: utf-8 -*-\n# 54판 v10 2026-09-27  (★제안서_PPT.py 가 이 줄의 v숫자로 새 판인지 가린다)\n"""54. 제안서 PPT - 회사 제안서의 고정 장을 그대로 가져오고, 현장 내용만 새로 만들어 붙인다.\n\n왜 이렇게 하는가\n  청담PJ 제안서(260715, 26장)를 뜯어보니 20장이 회사개요·핵심경쟁력·제품·납품실적·A/S 였다.\n  이 20장은 현장이 바뀌어도 그대로다. 다시 그리면 사진·마감이 원본보다 나빠질 뿐이다.\n  그래서 고정 장은 원본 pptx 에서 통째로 복사하고, 현장별로 바뀌는 장만 파이썬이 만든다.\n\n쓰는 법\n  3_공통사용\\\\원틀\\\\제안서\\\\ 안에 회사 제안서 pptx 를 넣어두고 이 도구를 누른다.\n  인터넷도 AI 도 쓰지 않는다. 사용료 0 원.\n"""\nimport os, io, json, copy, datetime\nfrom common import *\n\nfrom pptx import Presentation\nfrom pptx.util import Inches\n\nimport deck_core as deck          # 슬라이드 그리는 부분. 메뉴 번호를 갖지 않는 부품이다\n\nSPECS = os.path.join(os.path.dirname(os.path.abspath(__file__)), \'제안서_내용\')\nSKIP_REL = (\'slideLayout\', \'notesSlide\', \'slideMaster\')\n\n# 고정 장 판별 키워드 (이 글자가 그 장에 있으면 고정 장으로 본다)\nFIXED_KEYS = (\'목차\', \'회사개요\', \'회사소개\', \'설립\', \'핵심경쟁력\', \'경쟁력\',\n              \'납품실적\', \'실적\', \'A/S\', \'AS \', \'사후관리\', \'유지보수\', \'무상보증\',\n              \'제품라인업\', \'시리즈\', \'원스톱\', \'Opera\', \'PMS 연동\', \'별첨\')\n\n\n# ---------- 슬라이드 복사 ----------\ndef copy_slide(src_slide, dst_prs, layout_idx=6):\n    dst = dst_prs.slides.add_slide(dst_prs.slide_layouts[layout_idx])\n    for ph in list(dst.shapes):\n        ph._element.getparent().remove(ph._element)\n    for shp in src_slide.shapes:\n        dst.shapes._spTree.append(copy.deepcopy(shp._element))\n    for rel in src_slide.part.rels.values():\n        if any(k in rel.reltype for k in SKIP_REL):\n            continue\n        if rel.is_external:\n            new_rId = dst.part.rels.get_or_add_ext_rel(rel.reltype, rel.target_ref)\n        else:\n            new_rId = dst.part.relate_to(rel.target_part, rel.reltype)\n        if new_rId != rel.rId:\n            for el in dst.shapes._spTree.iter():\n                for k, v in list(el.attrib.items()):\n                    if v == rel.rId and (k.endswith(\'}embed\') or k.endswith(\'}id\')\n                                         or k.endswith(\'}link\')):\n                        el.attrib[k] = new_rId\n    return dst\n\n\ndef slide_text(s, limit=60):\n    out = []\n    for sh in s.shapes:\n        if sh.has_text_frame and sh.text_frame.text.strip():\n            out.append(sh.text_frame.text.strip().replace(\'\\n\', \' \'))\n    t = \' / \'.join(out)\n    return t[:limit] if t else \'(글자 없음)\'\n\n\ndef scan_source(path):\n    """원본 pptx 의 장별 요약과 고정 장 후보를 낸다."""\n    prs = Presentation(path)\n    rows = []\n    for i, s in enumerate(prs.slides, 1):\n        t = slide_text(s, 200)\n        pics = sum(1 for sh in s.shapes if sh.shape_type == 13)\n        fixed = any(k in t for k in FIXED_KEYS)\n        rows.append({\'no\': i, \'text\': t, \'pics\': pics, \'fixed\': fixed})\n    return prs, rows\n\n\ndef find_sources():\n    """원틀\\\\제안서 폴더에서 pptx 를 찾는다. 없으면 _원틀 전체에서 \'제안\' 들어간 것."""\n    cands = []\n    roots = []\n    # 원틀 폴더 (설정.ini 의 template, 기본 _원틀) + 공통사용\\원틀\\제안서\n    for key in (\'template\', \'base\'):\n        try:\n            v = cfg(key)\n        except Exception:\n            v = None\n        if not v:\n            continue\n        if key == \'base\':\n            for sub in ((\'3_공통사용\', \'원틀\', \'제안서\'), (\'3_공통사용\', \'원틀\'), (\'_원틀\', \'제안서\')):\n                roots.append(os.path.join(v, *sub))\n        else:\n            roots.append(v)\n    # _도구결과 는 보지 않는다 - 54번이 만든 합본이 다시 원본으로 잡히면 안 된다\n    roots.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), \'..\', \'..\'))\n    seen = set()\n    for r in roots:\n        if not r or not os.path.isdir(r):\n            continue\n        for dirpath, dirs, files in os.walk(r):\n            if \'제안\' not in dirpath and \'원틀\' not in dirpath:\n                continue\n            for f in files:\n                if f.lower().endswith(\'.pptx\') and not f.startswith(\'~$\'):\n                    p = os.path.join(dirpath, f)\n                    key = os.path.normcase(os.path.realpath(p))\n                    if key not in seen:\n                        seen.add(key)\n                        cands.append(p)\n    return sorted(cands)\n\n\n# ---------- 27번(도면수량) 결과를 그대로 제안서에 꽂는다 ----------\ndef find_qty_csv(site):\n    """_도구결과\\\\도면수량\\\\ 에서 그 현장의 가장 최근 도면수량 csv 를 찾는다."""\n    import glob\n    try:\n        root = os.path.join(cfg(\'out\'), \'도면수량\')\n    except Exception:\n        return None\n    if not os.path.isdir(root):\n        return None\n    pat = os.path.join(root, \'*\', \'*도면수량*.csv\')\n    cands = [p for p in glob.glob(pat)\n             if (not site) or safe_name(site) in os.path.basename(p)]\n    if not cands:\n        return None\n    cands.sort(key=lambda p: os.path.getmtime(p))\n    return cands[-1]\n\n\ndef read_qty(path):\n    """품목 / 채택수량 / 채택근거 만 뽑는다. 수량 0 이거나 비어 있으면 버린다."""\n    import csv\n    rows = []\n    site = \'\'\n    for enc in (\'utf-8-sig\', \'cp949\', \'utf-8\'):\n        try:\n            with io.open(path, encoding=enc) as fp:\n                for r in csv.reader(fp):\n                    if not r:\n                        continue\n                    if r[0] == \'[현장]\' and len(r) > 1:\n                        site = r[1]\n                    if r[0] in (\'품목\', \'[현장]\', \'[읽은 파일]\', \'[규칙 대조]\', \'\'):\n                        continue\n                    qty = (r[3] if len(r) > 3 else \'\').strip()\n                    if not qty or qty in (\'0\', \'-\'):\n                        continue\n                    rows.append([r[0].strip(), qty, (r[4] if len(r) > 4 else \'\').strip()])\n            break\n        except Exception:\n            continue\n    return site, rows\n\n\ndef qty_slides(site, rows, src_name=\'\'):\n    """도면에서 읽은 물량으로 「그 현장 이야기」 2장을 만든다."""\n    head = [\'품목\', \'수량\', \'근거\']\n    body = [[a, b, c or \'도면 판독\'] for a, b, c in rows[:9]]\n    t = {\'type\': \'table\', \'title\': \'%s 물량 (도면에서 읽은 값)\' % (site or \'본 현장\'),\n         \'eyebrow\': \'그 현장 이야기\', \'pill\': \'도면 기준\',\n         \'headers\': head, \'colW\': [3.6, 1.8, 3.6], \'rows\': body,\n         \'note\': \'이 표는 도면을 기계로 읽어 센 값입니다. 발주처 수량표와 대조해 확정합니다.\'\n                 + ((\'  (읽은 도면: %s)\' % src_name) if src_name else \'\')}\n    it = {\'type\': \'items\', \'title\': \'%s 적용 범위\' % (site or \'본 현장\'),\n          \'eyebrow\': \'그 현장 이야기\',\n          \'lead\': \'위 물량을 기준으로 당사가 공급·시공하는 범위입니다.\',\n          \'items\': [\n              {\'text\': \'CB 외함 제작 · 현장 납품\', \'desc\': \'선납품\'},\n              {\'text\': \'제어 분전함(속판) 설치 · 약전 결선\', \'desc\': \'객실관리\'},\n              {\'text\': \'객실 기구물 제작 · 설치\', \'desc\': \'벽지·페인트 완료 후\'},\n              {\'text\': \'시운전 및 운영자 인계 교육\', \'desc\': \'전원 공급 후\'}],\n          \'box\': {\'title\': \'확인 · 협의 사항\', \'lines\': [\n              \'조명 스위치 구수는 전등 설계가 나와야 확정됩니다. 도면에는 L 로만 표기합니다.\',\n              \'도면에서 읽지 못한 기호는 별도 목록으로 정리해 두었습니다. 함께 확인 부탁드립니다.\',\n              \'강전 결선과 외함 취부는 전기공사 범위입니다.\']}}\n    return [t, it]\n\n\n# ---------- 조립 ----------\ndef build_merged(spec, src_path, fixed_nos, out_path, mapping):\n    prs = Presentation()\n    prs.slide_width = Inches(deck.SLIDE_W)\n    prs.slide_height = Inches(deck.SLIDE_H)\n    foot = spec.get(\'footer\', \'한국마이크로닉(주)\')\n    made = 0\n    page = 0\n    for sl in spec.get(\'slides\', []):\n        fn = deck.KIND.get(sl.get(\'type\'))\n        if not fn:\n            continue\n        s = prs.slides.add_slide(prs.slide_layouts[6])\n        fn(s, sl)\n        if sl.get(\'type\') not in (\'cover\', \'request\'):\n            page += 1\n            deck._footer(s, foot, page)\n        made += 1\n    copied = 0\n    if src_path and fixed_nos:\n        src = Presentation(src_path)\n        n = len(src.slides)\n        for no in fixed_nos:\n            if 1 <= no <= n:\n                copy_slide(src.slides[no - 1], prs)\n                copied += 1\n    prs.save(out_path)\n    return made, copied\n\n\ndef run():\n    title(\'39. 제안서 PPT (회사 원본 + 현장 내용 합본)\')\n    # 1) 원본 고르기\n    srcs = find_sources()\n    src_path = None\n    fixed_nos = []\n    if srcs:\n        print(\'\')\n        print(\'찾은 회사 제안서 %s개\' % won(len(srcs)))\n        for i, p in enumerate(srcs, 1):\n            print(\' %2d. %s\' % (i, os.path.basename(p)))\n        s = ask(\'번호 (엔터 = 안 붙이고 현장 내용만) > \').strip()\n        if s.isdigit() and 1 <= int(s) <= len(srcs):\n            src_path = srcs[int(s) - 1]\n    else:\n        print(\'\')\n        print(\'회사 제안서 pptx 를 못 찾았습니다.\')\n        print(\'3_공통사용\\\\원틀\\\\제안서\\\\ 안에 넣어두시면 다음부터 자동으로 찾습니다.\')\n        print(\'지금은 현장 내용만 만듭니다.\')\n\n    if src_path:\n        prs, rows = scan_source(src_path)\n        print(\'\')\n        print(\'%s : 모두 %s장\' % (os.path.basename(src_path), won(len(rows))))\n        auto = [r[\'no\'] for r in rows if r[\'fixed\']]\n        for r in rows:\n            print(\' %s %2d. %s%s\' % (\'[고정]\' if r[\'fixed\'] else \'      \',\n                                     r[\'no\'],\n                                     (\'사진%d \' % r[\'pics\']) if r[\'pics\'] else \'\',\n                                     r[\'text\'][:58]))\n        print(\'\')\n        print(\'[고정] 으로 잡은 장 : %s\' % (\',\'.join(str(x) for x in auto) if auto else \'없음\'))\n        s = ask(\'그대로 쓰려면 엔터, 바꾸려면 번호를 쉼표로 (예 2,3,4,13-20) > \').strip()\n        fixed_nos = parse_nos(s) if s else auto\n\n    # 2) 현장 내용 고르기\n    specs = []\n    if os.path.isdir(SPECS):\n        for name in sorted(os.listdir(SPECS)):\n            if name.lower().endswith(\'.json\'):\n                try:\n                    specs.append((os.path.join(SPECS, name),\n                                  json.loads(io.open(os.path.join(SPECS, name),\n                                                     encoding=\'utf-8\').read())))\n                except Exception as e:\n                    print(\'  건너뜀 : %s (%s)\' % (name, e))\n    if not specs:\n        print(\'제안서_내용 폴더에 json 이 없습니다.\')\n        return\n    print(\'\')\n    print(\'현장 내용 %s건\' % won(len(specs)))\n    for i, (p, d) in enumerate(specs, 1):\n        print(\' %2d. %s  (%d장)\' % (i, d.get(\'title\', \'?\'), len(d.get(\'slides\', []))))\n    sel = ask(\'\\n번호 (엔터 = 전부) > \')\n    pick = [specs[int(sel) - 1]] if sel.isdigit() and 1 <= int(sel) <= len(specs) else specs\n    site = ask(\'현장명 (엔터 = 현장명 없는 범용 표준본) > \').strip()\n\n    # 27번 도면수량 결과가 있으면 「그 현장 이야기」 2장을 자동으로 끼운다\n    qrows = []\n    qcsv = find_qty_csv(site)\n    if qcsv:\n        qsite, qrows = read_qty(qcsv)\n        if qrows:\n            print(\'\')\n            print(\'도면수량 결과를 찾았습니다 : %s\' % os.path.basename(qcsv))\n            print(\'  품목 %s개를 제안서에 그대로 넣습니다.\' % won(len(qrows)))\n            for a, b, c in qrows[:6]:\n                print(\'   - %s : %s (%s)\' % (a, b, c or \'도면 판독\'))\n        else:\n            print(\'\')\n            print(\'도면수량 파일은 있으나 채택수량이 비어 있습니다. 물량 장은 넣지 않습니다.\')\n    elif site:\n        print(\'\')\n        print(\'27번 도면수량 결과가 없습니다. 도면을 넣고 27번을 먼저 누르시면\')\n        print(\'그 현장 물량이 제안서에 자동으로 들어갑니다.\')\n\n    od = outdir(\'제안서PPT\')\n    mapping = {\'{{현장}}\': site if site else \'귀사\',\n               \'{{현장_제목}}\': (site + \' \') if site else \'\',\n               \'{{날짜}}\': today().strftime(\'%Y. %m. %d\')}\n    print(\'\')\n    checked = []                       # (파일, 문제 목록, 메모) - 만든 뒤 바로 점검 (deck_check)\n    for p, d in pick:\n        d2 = deck.fill(d, mapping)\n        if qrows:\n            sl = d2.setdefault(\'slides\', [])\n            at = 1 if sl and sl[0].get(\'type\') == \'cover\' else 0\n            for k, extra in enumerate(qty_slides(site, qrows, os.path.basename(qcsv))):\n                sl.insert(at + k, extra)\n        base = \'%s_%s_%s_r1.pptx\' % (safe_name(site or \'표준\'),\n                                     safe_name(d2.get(\'파일명\', d2.get(\'title\', \'제안서\'))[:30]),\n                                     ymd6())\n        f = os.path.join(od, base)\n        try:\n            made, copied = build_merged(d2, src_path, fixed_nos, f, mapping)\n            print(\'만듦 : %s  (새로 %d장 + 원본에서 %d장 = %d장)\'\n                  % (f, made, copied, made + copied))\n            checked.append(f)\n            deck_check_report(f, checked)\n        except Exception as e:\n            print(\'실패 : %s  (%s)\' % (d2.get(\'title\'), e))\n    print(\'\')\n    deck_check_summary(checked, od)\n    print(\'대외 제출 전 반드시 한 번 열어 확인하십시오.\')\n    log(\'제안서PPT\', \'%d건 %s\' % (len(pick), site or \'범용\'))\n\n\n\n# ---------- 만든 뒤 바로 점검 (deck_check : 글자 넘침·겹침·붙음·표 밀림) ----------\n_CHECK = {}\n\n\ndef deck_check_report(f, checked):\n    """한 파일 점검. deck_check 가 없거나 실패해도 제안서 만들기는 멈추지 않는다."""\n    try:\n        import deck_check\n        probs, note = deck_check.check(f)\n    except Exception as e:\n        _CHECK[f] = (None, \'점검 못 함 (%s)\' % e)\n        print(\'  점검 : 못 함 (%s)\' % e)\n        return\n    _CHECK[f] = (probs, note)\n    if not probs:\n        print(\'  점검 : 이상 없음\')\n    else:\n        print(\'  점검 : 확인할 곳 %d군데\' % len(probs))\n        for si, kind, msg in probs:\n            print(\'     %2d장 %-4s %s\' % (si, kind, msg))\n\n\ndef deck_check_summary(checked, od):\n    """모아서 한 줄 + 점검결과 txt (창을 닫아도 남게)"""\n    if not checked:\n        return\n    bad = [(f, _CHECK.get(f, (None, \'\'))) for f in checked]\n    n = sum(len(v[0]) for f, v in bad if v[0])\n    lines = [\'제안서 점검 %s  (%s)\' % (today().strftime(\'%Y-%m-%d\'), next((v[1] for f, v in bad if v[1]), \'\'))]\n    for f, (probs, note) in bad:\n        if probs is None:\n            lines.append(\'%s : 점검 못 함\' % os.path.basename(f))\n        elif probs:\n            lines.append(\'%s : 확인할 곳 %d군데\' % (os.path.basename(f), len(probs)))\n            lines += [\'   %2d장 %s  %s\' % (si, kind, msg) for si, kind, msg in probs]\n        else:\n            lines.append(\'%s : 이상 없음\' % os.path.basename(f))\n    print(\'점검 : %s\' % (\'전부 이상 없음 (%d개)\' % len(checked) if not n else\n                         \'확인할 곳 %d군데 - 위 장 번호를 파워포인트에서 열어 보십시오\' % n))\n    try:\n        with io.open(os.path.join(od, \'_점검결과_%s.txt\' % ymd6()), \'w\', encoding=\'utf-8-sig\') as fp:\n            fp.write(\'\\r\\n\'.join(lines) + \'\\r\\n\')\n    except Exception:\n        pass\n\ndef parse_nos(s):\n    out = []\n    for part in s.replace(\' \', \'\').split(\',\'):\n        if not part:\n            continue\n        if \'-\' in part:\n            a, b = part.split(\'-\')[:2]\n            if a.isdigit() and b.isdigit():\n                out.extend(range(int(a), int(b) + 1))\n        elif part.isdigit():\n            out.append(int(part))\n    return out\n\n\nif __name__ == \'__main__\':\n    run(); pause()\n',
    'deck_core.py': '# -*- coding: utf-8 -*-\n# 54판 v10 2026-09-27  (★제안서_PPT.py 가 이 줄의 v숫자로 새 판인지 가린다)\n"""deck_core - 회사 표준 서식으로 슬라이드를 그리는 부품. 메뉴 번호 없음.\n\n54번(t54_deck)이 이것을 불러 쓴다. 단독으로 실행하지 않는다.\n\n10번(t15 제안서 후보+초안)과 역할이 다르다.\n  10번 = 회의록에서 "자료 달라"는 말을 찾아 무엇을 만들지 고르는 것 (txt 초안)\n  26번 = 고른 것을 실제 제출 가능한 pptx 로 뽑는 것\n\n내용은 이미 json 안에 다 들어 있으므로 이 도구는 인터넷도 AI 도 쓰지 않는다. 토큰 0.\n현장명을 물어 {{현장}} 자리에 넣으므로, 같은 내용으로 범용본과 현장 맞춤본 둘 다 나온다.\n"""\nimport os, io, json, datetime\nfrom common import *\n\nfrom pptx import Presentation\nfrom pptx.util import Inches, Pt, Emu\nfrom pptx.dml.color import RGBColor\nfrom pptx.enum.text import PP_ALIGN, MSO_ANCHOR\nfrom pptx.enum.shapes import MSO_SHAPE\n\n# -- 회사 표준 디자인 (km-proposal 빌더와 같은 값. 바꾸지 말 것) --\nNAVY = RGBColor(0x1F, 0x38, 0x64)\nNAVY_D = RGBColor(0x17, 0x28, 0x4A)\nBLUE = RGBColor(0x2E, 0x74, 0xB5)\nRED = RGBColor(0xC0, 0x00, 0x00)\nGREEN_BG = RGBColor(0xE2, 0xEF, 0xD9)\nGREEN_TX = RGBColor(0x37, 0x56, 0x23)\nGRAY_BG = RGBColor(0xF2, 0xF2, 0xF2)\nGRAY_TX = RGBColor(0x59, 0x59, 0x59)\nLINE = RGBColor(0xD9, 0xD9, 0xD9)\nWHITE = RGBColor(0xFF, 0xFF, 0xFF)\nBODY = RGBColor(0x33, 0x33, 0x33)\nSKY = RGBColor(0xDE, 0xEA, 0xF6)\nFONT = \'맑은 고딕\'\n\nML, MW, MTOP = 0.5, 9.0, 0.45\nSLIDE_W, SLIDE_H = 10.0, 5.625\n\nSPECS = os.path.join(os.path.dirname(os.path.abspath(__file__)), \'제안서_내용\')\n\n\n# ---------- 기본 그리기 ----------\ndef _tb(slide, x, y, w, h, text, size=11, color=BODY, bold=False,\n        align=PP_ALIGN.LEFT, anchor=MSO_ANCHOR.TOP, space=2):\n    box = slide.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h))\n    tf = box.text_frame\n    tf.word_wrap = True\n    tf.margin_left = tf.margin_right = 0\n    tf.margin_top = tf.margin_bottom = 0\n    tf.vertical_anchor = anchor\n    lines = str(text).split(\'\\n\')\n    for i, ln in enumerate(lines):\n        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()\n        p.alignment = align\n        p.space_after = Pt(space)\n        r = p.add_run()\n        r.text = ln\n        r.font.name = FONT\n        r.font.size = Pt(size)\n        r.font.bold = bold\n        r.font.color.rgb = color\n    return box\n\n\ndef _rect(slide, x, y, w, h, fill=None, line=None, shape=MSO_SHAPE.RECTANGLE, lw=1.0):\n    s = slide.shapes.add_shape(shape, Inches(x), Inches(y), Inches(w), Inches(h))\n    if fill is None:\n        s.fill.background()\n    else:\n        s.fill.solid()\n        s.fill.fore_color.rgb = fill\n    if line is None:\n        s.line.fill.background()\n    else:\n        s.line.color.rgb = line\n        s.line.width = Pt(lw)\n    s.shadow.inherit = False\n    if s.has_text_frame:\n        s.text_frame.text = \'\'\n    return s\n\n\ndef _blank(prs):\n    return prs.slides.add_slide(prs.slide_layouts[6])\n\n\ndef _footer(slide, note, page=None):\n    _tb(slide, ML, 5.22, MW - 0.6, 0.25, note or \'한국마이크로닉(주)\', size=8, color=GRAY_TX)\n    if page:\n        _tb(slide, ML + MW - 0.6, 5.22, 0.6, 0.25, str(page), size=8.5, color=NAVY,\n            bold=True, align=PP_ALIGN.RIGHT)\n\n\ndef _fit(text, w, h, size, bold=True, min_size=12, space=2):\n    """상자(w×h 인치)에 들어갈 때까지 글자 크기를 1pt 씩 줄인다. 현장명이 길 때 표지·제목이 넘치지 않게.\n    재는 법은 deck_check(맑은 고딕 폭)와 같다. deck_check 가 없으면 원래 크기 그대로."""\n    try:\n        import deck_check as dc\n    except Exception:\n        return size\n    s = float(size)\n    paras = str(text).split(\'\\n\')\n    while s > min_size:\n        n = sum(len(dc._wrap(pp, w, s, bold)) for pp in paras)\n        if n * dc._lh(s, bold) + (len(paras) - 1) * space / 72.0 <= h + 0.01:\n            return s\n        s -= 1\n    return float(min_size)\n\n\ndef _page_title(slide, title_text, eyebrow=None, pill=None):\n    y = MTOP\n    if eyebrow:\n        _tb(slide, ML, y, 6.0, 0.22, eyebrow, size=9, color=GRAY_TX)\n        y += 0.24\n    pw = min(3.2, 0.14 * len(pill) + 0.5) if pill else 0.0\n    tw = min(7.0, MW - pw - 0.15) if pill else 7.0\n    _tb(slide, ML, y, tw, 0.42, title_text, size=_fit(title_text, tw, 0.42, 19, True, 13), color=NAVY, bold=True)\n    if pill:\n        w = pw\n        _rect(slide, ML + MW - w, y + 0.04, w, 0.3, fill=SKY, line=None,\n              shape=MSO_SHAPE.ROUNDED_RECTANGLE)\n        _tb(slide, ML + MW - w, y + 0.08, w, 0.24, pill, size=9, color=NAVY,\n            bold=True, align=PP_ALIGN.CENTER)\n    y += 0.5\n    _rect(slide, ML, y, MW, 0.02, fill=NAVY)\n    return y + 0.18\n\n\n# ---------- 슬라이드 종류 ----------\ndef s_cover(slide, d):\n    _rect(slide, 0, 0, SLIDE_W, SLIDE_H, fill=NAVY)\n    _rect(slide, 0, 0, 0.18, SLIDE_H, fill=BLUE)\n    _tb(slide, 1.0, 1.55, 8.2, 0.3, d.get(\'eyebrow\', \'\'), size=11, color=SKY, bold=True)\n    t = d.get(\'title\', \'\')\n    _tb(slide, 1.0, 1.95, 8.2, 1.1, t, size=_fit(t, 8.2, 1.1, 30, True, 18, space=4), color=WHITE, bold=True, space=4)\n    if d.get(\'subtitle\'):\n        _tb(slide, 1.0, 3.15, 8.2, 0.5, d[\'subtitle\'], size=14, color=SKY)\n    _rect(slide, 1.0, 3.85, 1.4, 0.03, fill=BLUE)\n    _tb(slide, 1.0, 4.1, 8.2, 0.4, d.get(\'meta\', \'\'), size=10.5, color=LINE)\n\n\ndef s_conclusion(slide, d):\n    y = _page_title(slide, d.get(\'title\', \'결론\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    if d.get(\'headline\'):\n        h = 0.62 if len(d[\'headline\']) < 60 else 0.85\n        _rect(slide, ML, y, MW, h, fill=GREEN_BG)\n        _tb(slide, ML + 0.18, y + 0.1, MW - 0.36, h - 0.2, d[\'headline\'], size=12.5,\n            color=GREEN_TX, bold=True, anchor=MSO_ANCHOR.MIDDLE)\n        y += h + 0.22\n    cards = d.get(\'cards\', [])\n    if cards:\n        n = len(cards)\n        gap = 0.18\n        cw = (MW - gap * (n - 1)) / n\n        ch = 1.55\n        for i, c in enumerate(cards):\n            x = ML + i * (cw + gap)\n            _rect(slide, x, y, cw, ch, fill=GRAY_BG, line=LINE)\n            _rect(slide, x, y, cw, 0.05, fill=BLUE)\n            _tb(slide, x + 0.14, y + 0.16, cw - 0.28, 0.24, c.get(\'label\', \'\'), size=9.5,\n                color=GRAY_TX, bold=True)\n            _tb(slide, x + 0.14, y + 0.44, cw - 0.28, 0.42, c.get(\'big\', \'\'), size=14,\n                color=NAVY, bold=True)\n            _tb(slide, x + 0.14, y + 0.92, cw - 0.28, ch - 1.02, c.get(\'body\', \'\'), size=9.5,\n                color=BODY)\n        y += ch + 0.2\n    if d.get(\'banner\'):\n        _rect(slide, ML, y, MW, 0.52, fill=None, line=RED, lw=1.25)\n        _tb(slide, ML + 0.16, y + 0.1, MW - 0.32, 0.34, d[\'banner\'], size=10,\n            color=RED, bold=True, anchor=MSO_ANCHOR.MIDDLE)\n\n\ndef s_table(slide, d):\n    y = _page_title(slide, d.get(\'title\', \'\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    headers = d.get(\'headers\', [])\n    rows = d.get(\'rows\', [])\n    colw = d.get(\'colW\') or [MW / max(1, len(headers))] * len(headers)\n    note_h = 0.34 if d.get(\'note\') else 0.0\n    avail = 5.05 - y - note_h\n    nrow = len(rows) + 1\n    rh = max(0.24, min(0.80, avail / nrow))\n    shape = slide.shapes.add_table(nrow, len(headers), Inches(ML), Inches(y),\n                                   Inches(sum(colw)), Inches(rh * nrow))\n    tbl = shape.table\n    tbl.first_row = True\n    for j, w in enumerate(colw):\n        tbl.columns[j].width = Inches(w)\n    for i in range(nrow):\n        tbl.rows[i].height = Inches(rh)\n    data = [headers] + rows\n    for i, row in enumerate(data):\n        for j, val in enumerate(row):\n            cell = tbl.cell(i, j)\n            cell.margin_left = Inches(0.08)\n            cell.margin_right = Inches(0.08)\n            cell.margin_top = Inches(0.03)\n            cell.margin_bottom = Inches(0.03)\n            cell.vertical_anchor = MSO_ANCHOR.MIDDLE\n            cell.fill.solid()\n            cell.fill.fore_color.rgb = NAVY if i == 0 else (\n                WHITE if i % 2 else RGBColor(0xF7, 0xF9, 0xFC))\n            tf = cell.text_frame\n            tf.word_wrap = True\n            for k, ln in enumerate(str(val).split(\'\\n\')):\n                p = tf.paragraphs[0] if k == 0 else tf.add_paragraph()\n                p.space_after = Pt(0)\n                r = p.add_run()\n                r.text = ln\n                r.font.name = FONT\n                r.font.size = Pt(9 if i == 0 else 8.5)\n                r.font.bold = (i == 0)\n                r.font.color.rgb = WHITE if i == 0 else BODY\n    if d.get(\'note\'):\n        _tb(slide, ML, y + rh * nrow + 0.08, MW, 0.3, \'※ \' + d[\'note\'], size=8.5, color=GRAY_TX)\n\n\ndef s_items(slide, d):\n    y = _page_title(slide, d.get(\'title\', \'\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    if d.get(\'lead\'):\n        _tb(slide, ML, y, MW, 0.3, d[\'lead\'], size=10.5, color=GRAY_TX)\n        y += 0.36\n    items = d.get(\'items\', [])\n    box = d.get(\'box\')\n    box_h = 0.0\n    if box:\n        box_h = 0.42 + 0.26 * len(box.get(\'lines\', []))\n    avail = 5.05 - y - (box_h + 0.18 if box else 0)\n    ih = min(0.62, max(0.34, avail / max(1, len(items))))\n    for i, it in enumerate(items):\n        yy = y + i * ih\n        _rect(slide, ML, yy + 0.03, 0.26, 0.26, fill=BLUE, shape=MSO_SHAPE.OVAL)\n        _tb(slide, ML, yy + 0.06, 0.26, 0.2, str(i + 1), size=9.5, color=WHITE,\n            bold=True, align=PP_ALIGN.CENTER)\n        _tb(slide, ML + 0.38, yy + 0.02, MW - 2.5, 0.28, it.get(\'text\', \'\'), size=11,\n            color=BODY, bold=True)\n        if it.get(\'desc\'):\n            _tb(slide, ML + MW - 2.0, yy + 0.04, 2.0, 0.26, \'[ %s ]\' % it[\'desc\'],\n                size=9.5, color=BLUE, bold=True, align=PP_ALIGN.RIGHT)\n    if box:\n        by = 5.05 - box_h\n        _rect(slide, ML, by, MW, box_h, fill=GRAY_BG, line=LINE)\n        _tb(slide, ML + 0.16, by + 0.08, MW - 0.32, 0.24,\n            box.get(\'title\', \'확인 · 협의 사항\'), size=10, color=NAVY, bold=True)\n        for i, ln in enumerate(box.get(\'lines\', [])):\n            _tb(slide, ML + 0.28, by + 0.36 + i * 0.26, MW - 0.5, 0.24, \'· \' + ln,\n                size=9.5, color=BODY)\n\n\ndef s_diagram(slide, d):\n    """구성도를 그림이 아니라 도형으로 그린다 - 파워포인트에서 직접 고칠 수 있다."""\n    y = _page_title(slide, d.get(\'title\', \'\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    if d.get(\'lead\'):\n        _tb(slide, ML, y, MW, 0.3, d[\'lead\'], size=10, color=GRAY_TX)\n        y += 0.34\n    STYLE = {\'main\': (NAVY, WHITE), \'device\': (SKY, NAVY), \'sub\': (GRAY_BG, GRAY_TX),\n             \'alert\': (RED, WHITE)}                      # alert = 법적 의무 등 빠지면 안 되는 것\n    canvas = d.get(\'canvas\', [10.0, 3.0])\n    steps = d.get(\'steps\', [])\n    ch = (1.55 if steps else 2.9)\n    sx, sy = MW / canvas[0], ch / canvas[1]\n    pos = {}\n    boxes = d.get(\'boxes\', [])\n\n    def _holds(o, i):                                     # o 가 i 를 품는가 (방 안의 표시)\n        return (o is not i and o[\'x\'] <= i[\'x\'] and o[\'y\'] <= i[\'y\']\n                and i[\'x\'] + i[\'w\'] <= o[\'x\'] + o[\'w\'] + 1e-6 and i[\'y\'] + i[\'h\'] <= o[\'y\'] + o[\'h\'] + 1e-6)\n    for b in boxes:\n        x = ML + b[\'x\'] * sx\n        yy = y + b[\'y\'] * sy\n        w, h = b[\'w\'] * sx, b[\'h\'] * sy\n        pos[b[\'id\']] = (x, yy, w, h)\n        fill, tx = STYLE.get(b.get(\'style\', \'sub\'), STYLE[\'sub\'])\n        _rect(slide, x, yy, w, h, fill=fill, line=LINE, shape=MSO_SHAPE.ROUNDED_RECTANGLE)\n        body = b.get(\'title\', \'\')\n        for ln in b.get(\'lines\', []):\n            body += \'\\n\' + ln\n        if any(_holds(b, o) for o in boxes):\n            # 방처럼 다른 표시를 품은 상자 : 이름을 오른쪽 아래 구석으로 (가운데 두면 표시와 겹친다)\n            _tb(slide, x + 0.06, yy + h - 0.3, w - 0.14, 0.26, body, size=b.get(\'fs\', 9),\n                color=tx, bold=True, align=PP_ALIGN.RIGHT, anchor=MSO_ANCHOR.BOTTOM, space=0)\n            continue\n        _tb(slide, x + 0.06, yy + 0.05, w - 0.12, h - 0.1, body, size=b.get(\'fs\', 9),\n            color=tx, bold=True, align=PP_ALIGN.CENTER, anchor=MSO_ANCHOR.MIDDLE, space=0)\n    for lk in d.get(\'links\', []):\n        a, b = pos.get(lk[\'from\']), pos.get(lk[\'to\'])\n        if not a or not b:\n            continue\n        col = BLUE if lk.get(\'style\', \'comm\') == \'comm\' else (\n            RED if lk[\'style\'] == \'power\' else GRAY_TX)\n        ac, bc = a[0] + a[2] / 2, b[0] + b[2] / 2\n        y_over = max(a[1], b[1]) < min(a[1] + a[3], b[1] + b[3])\n        x_over = max(a[0], b[0]) < min(a[0] + a[2], b[0] + b[2])\n        if abs(a[1] - b[1]) < 0.05 or (y_over and not x_over):   # 가로\n            x1 = (a[0] + a[2]) if a[0] < b[0] else (b[0] + b[2])\n            x2 = b[0] if a[0] < b[0] else a[0]\n            if abs(a[1] - b[1]) < 0.05:\n                yy = a[1] + a[3] / 2\n            else:\n                yy = (max(a[1], b[1]) + min(a[1] + a[3], b[1] + b[3])) / 2\n            _rect(slide, x1, yy - 0.01, max(0.02, x2 - x1), 0.025, fill=col)\n            if lk.get(\'label\'):\n                _tb(slide, x1, yy - 0.28, max(0.5, x2 - x1), 0.24, lk[\'label\'], size=8,\n                    color=col, bold=True, align=PP_ALIGN.CENTER)\n        elif x_over:                                      # 세로\n            if b[0] <= ac <= b[0] + b[2]:\n                xx = ac\n            elif a[0] <= bc <= a[0] + a[2]:\n                xx = bc\n            else:\n                xx = (max(a[0], b[0]) + min(a[0] + a[2], b[0] + b[2])) / 2\n            y1 = (a[1] + a[3]) if a[1] < b[1] else (b[1] + b[3])\n            y2 = b[1] if a[1] < b[1] else a[1]\n            _rect(slide, xx - 0.01, y1, 0.025, max(0.02, y2 - y1), fill=col)\n            if lk.get(\'label\'):\n                _tb(slide, xx + 0.08, y1, 2.4, 0.22, lk[\'label\'], size=8, color=col, bold=True)\n        else:                                             # 대각 자리 -> ㄱ자로 꺾는다\n            top, low = (a, b) if a[1] < b[1] else (b, a)\n            tx = top[0] + top[2] / 2                      # 위 상자 아래 가운데에서 내려와\n            my = low[1] + low[3] / 2                      # 아래 상자 가운데 높이에서 꺾는다\n            _rect(slide, tx - 0.01, top[1] + top[3], 0.025, max(0.02, my - top[1] - top[3]), fill=col)\n            if low[0] > tx:\n                x1, x2 = tx, low[0]\n            else:\n                x1, x2 = low[0] + low[2], tx\n            _rect(slide, x1 - 0.01, my - 0.01, max(0.02, x2 - x1) + 0.02, 0.025, fill=col)\n            if lk.get(\'label\'):\n                _tb(slide, x1, my - 0.28, max(0.5, x2 - x1), 0.24, lk[\'label\'], size=8,\n                    color=col, bold=True, align=PP_ALIGN.CENTER)\n    if steps:\n        by = 5.05 - 1.15\n        n = len(steps)\n        gap = 0.14\n        cw = (MW - gap * (n - 1)) / n\n        for i, st in enumerate(steps):\n            x = ML + i * (cw + gap)\n            _rect(slide, x, by, cw, 1.1, fill=GRAY_BG, line=LINE)\n            _rect(slide, x + 0.1, by + 0.1, 0.24, 0.24, fill=BLUE, shape=MSO_SHAPE.OVAL)\n            _tb(slide, x + 0.1, by + 0.13, 0.24, 0.2, st.get(\'num\', str(i + 1)), size=9,\n                color=WHITE, bold=True, align=PP_ALIGN.CENTER)\n            _tb(slide, x + 0.42, by + 0.12, cw - 0.52, 0.24, st.get(\'text\', \'\'), size=9.5,\n                color=NAVY, bold=True)\n            _tb(slide, x + 0.1, by + 0.42, cw - 0.2, 0.22, \'[ %s ]\' % st.get(\'who\', \'\'),\n                size=8.5, color=BLUE, bold=True)\n            _tb(slide, x + 0.1, by + 0.66, cw - 0.2, 0.4, st.get(\'desc\', \'\'), size=8, color=BODY)\n\n\ndef s_split(slide, d):\n    """좌우 비교. 박스 높이는 줄 수에 맞춘다 (빈 박스가 아래로 길게 남지 않게)."""\n    y = _page_title(slide, d.get(\'title\', \'\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    cw = (MW - 0.24) / 2\n    n = max([len(d.get(sd, {}).get(\'lines\', [])) for sd in (\'left\', \'right\')] + [1])\n    step = 0.42\n    h = min(5.0 - y, 0.66 + n * step + 0.18)\n    for i, side in enumerate((\'left\', \'right\')):\n        blk = d.get(side, {})\n        x = ML + i * (cw + 0.24)\n        _rect(slide, x, y, cw, h, fill=(GRAY_BG if i == 0 else SKY), line=LINE)\n        _rect(slide, x, y, cw, 0.05, fill=(GRAY_TX if i == 0 else BLUE))\n        _tb(slide, x + 0.18, y + 0.16, cw - 0.36, 0.32, blk.get(\'label\', \'\'), size=12.5,\n            color=(GRAY_TX if i == 0 else NAVY), bold=True)\n        for j, ln in enumerate(blk.get(\'lines\', [])):\n            _tb(slide, x + 0.3, y + 0.66 + j * step, cw - 0.5, 0.34, \'· \' + ln, size=11,\n                color=BODY)\n    if d.get(\'note\') and y + h + 0.7 <= 5.05:\n        _rect(slide, ML, y + h + 0.2, MW, 0.5, fill=GREEN_BG)\n        _tb(slide, ML + 0.2, y + h + 0.2, MW - 0.4, 0.5, d[\'note\'], size=11, color=NAVY,\n            bold=True, anchor=MSO_ANCHOR.MIDDLE)\n\n\ndef s_request(slide, d):\n    _rect(slide, 0, 0, SLIDE_W, SLIDE_H, fill=NAVY)\n    _rect(slide, 0, 0, 0.18, SLIDE_H, fill=BLUE)\n    _tb(slide, 0.9, 0.55, 8.4, 0.45, d.get(\'title\', \'요청드리는 사항\'), size=22,\n        color=WHITE, bold=True)\n    if d.get(\'lead\'):\n        _tb(slide, 0.9, 1.08, 8.4, 0.3, d[\'lead\'], size=11, color=SKY)\n    y = 1.6\n    for i, it in enumerate(d.get(\'items\', [])):\n        _rect(slide, 0.9, y + 0.02, 0.26, 0.26, fill=BLUE, shape=MSO_SHAPE.OVAL)\n        _tb(slide, 0.9, y + 0.05, 0.26, 0.2, str(i + 1), size=9.5, color=WHITE,\n            bold=True, align=PP_ALIGN.CENTER)\n        _tb(slide, 1.3, y, 8.0, 0.28, it.get(\'text\', \'\'), size=12, color=WHITE, bold=True)\n        if it.get(\'desc\'):\n            _tb(slide, 1.3, y + 0.3, 8.0, 0.26, it[\'desc\'], size=9.5, color=LINE)\n        y += 0.72\n    if d.get(\'contact\'):\n        _rect(slide, 0.9, 4.75, 8.4, 0.02, fill=BLUE)\n        _tb(slide, 0.9, 4.9, 8.4, 0.3, d[\'contact\'], size=10, color=SKY)\n\n\n\n\ndef s_toc(slide, d):\n    y = _page_title(slide, d.get(\'title\', \'목차\'), d.get(\'eyebrow\', \'CONTENTS\'))\n    items = d.get(\'items\', [])\n    n = max(1, len(items))\n    h = min(0.72, (5.0 - y) / n)\n    for i, it in enumerate(items):\n        yy = y + i * h\n        _rect(slide, ML, yy + 0.04, 0.42, h - 0.14, fill=NAVY)\n        _tb(slide, ML, yy + 0.08, 0.42, h - 0.22, \'%02d\' % (i + 1), size=11,\n            color=WHITE, bold=True, align=PP_ALIGN.CENTER, anchor=MSO_ANCHOR.MIDDLE)\n        _tb(slide, ML + 0.58, yy + 0.06, 5.4, 0.3, it.get(\'text\', \'\'), size=12.5,\n            color=NAVY, bold=True)\n        if it.get(\'desc\'):\n            _tb(slide, ML + 0.58, yy + 0.34, 5.4, 0.26, it[\'desc\'], size=9.5, color=GRAY_TX)\n        if it.get(\'page\'):\n            _tb(slide, ML + MW - 1.2, yy + 0.08, 1.2, 0.28, str(it[\'page\']), size=10.5,\n                color=BLUE, bold=True, align=PP_ALIGN.RIGHT)\n        _rect(slide, ML, yy + h - 0.06, MW, 0.01, fill=LINE)\n\n\nYELLOW = RGBColor(0xFF, 0xF8, 0xDC)\n\n\ndef s_reply(slide, d):\n    """질의 · 당사 답변 · 귀사 회신란(빈칸). 협의서는 답이 돌아와야 완성이다."""\n    y = _page_title(slide, d.get(\'title\', \'질의 · 답변\'), d.get(\'eyebrow\'), d.get(\'pill\'))\n    rows = d.get(\'rows\', [])\n    heads = [\'No\', \'질의 · 협의 항목\', \'당사 답변\', \'귀사 회신\']\n    colw = [0.45, 2.55, 3.4, 2.6]\n    nrow = len(rows) + 1\n    avail = 5.0 - y - (0.32 if d.get(\'note\') else 0)\n    rh = max(0.3, min(0.78, avail / nrow))\n    tbl = slide.shapes.add_table(nrow, 4, Inches(ML), Inches(y), Inches(sum(colw)),\n                                 Inches(rh * nrow)).table\n    for j, w in enumerate(colw):\n        tbl.columns[j].width = Inches(w)\n    for i in range(nrow):\n        tbl.rows[i].height = Inches(rh)\n    data = [heads] + [[str(k + 1), r.get(\'item\', \'\'), r.get(\'ours\', \'\'), r.get(\'theirs\', \'\')]\n                      for k, r in enumerate(rows)]\n    for i, row in enumerate(data):\n        for j, val in enumerate(row):\n            c = tbl.cell(i, j)\n            c.margin_left = c.margin_right = Inches(0.07)\n            c.vertical_anchor = MSO_ANCHOR.MIDDLE\n            c.fill.solid()\n            if i == 0:\n                c.fill.fore_color.rgb = NAVY\n            elif j == 3:\n                c.fill.fore_color.rgb = YELLOW\n            else:\n                c.fill.fore_color.rgb = WHITE if i % 2 else RGBColor(0xF7, 0xF9, 0xFC)\n            tf = c.text_frame\n            tf.word_wrap = True\n            for k, ln in enumerate(str(val).split(\'\\n\')):\n                para = tf.paragraphs[0] if k == 0 else tf.add_paragraph()\n                r = para.add_run()\n                r.text = ln\n                r.font.name = FONT\n                r.font.size = Pt(9 if i == 0 else 8.5)\n                r.font.bold = (i == 0 or j == 0)\n                r.font.color.rgb = WHITE if i == 0 else BODY\n                if j == 0:\n                    para.alignment = PP_ALIGN.CENTER\n    if d.get(\'note\'):\n        _tb(slide, ML, y + rh * nrow + 0.08, MW, 0.3, \'※ \' + d[\'note\'], size=8.5, color=GRAY_TX)\n\nKIND = {\'cover\': s_cover, \'toc\': s_toc, \'reply\': s_reply, \'conclusion\': s_conclusion, \'table\': s_table, \'items\': s_items,\n        \'diagram\': s_diagram, \'split\': s_split, \'request\': s_request}\n\n\n# ---------- 조립 ----------\ndef fill(obj, mapping):\n    if isinstance(obj, str):\n        for k, v in mapping.items():\n            obj = obj.replace(k, v)\n        return obj\n    if isinstance(obj, list):\n        return [fill(x, mapping) for x in obj]\n    if isinstance(obj, dict):\n        return dict((k, fill(v, mapping)) for k, v in obj.items())\n    return obj\n\n\ndef build(spec, out_path):\n    prs = Presentation()\n    prs.slide_width = Inches(SLIDE_W)\n    prs.slide_height = Inches(SLIDE_H)\n    foot = spec.get(\'footer\', \'한국마이크로닉(주)\')\n    page = 0\n    for i, sl in enumerate(spec.get(\'slides\', [])):\n        fn = KIND.get(sl.get(\'type\'))\n        if not fn:\n            raise ValueError(\'모르는 슬라이드 종류: %s (%d번째 장)\' % (sl.get(\'type\'), i + 1))\n        slide = _blank(prs)\n        fn(slide, sl)\n        if sl.get(\'type\') not in (\'cover\', \'request\'):\n            page += 1\n            _footer(slide, foot, page)\n    prs.save(out_path)\n    return len(spec.get(\'slides\', []))\n\n\ndef load_specs():\n    out = []\n    if not os.path.isdir(SPECS):\n        return out\n    for name in sorted(os.listdir(SPECS)):\n        if not name.lower().endswith(\'.json\'):\n            continue\n        p = os.path.join(SPECS, name)\n        try:\n            d = json.loads(io.open(p, encoding=\'utf-8\').read())\n            out.append((p, d))\n        except Exception as e:\n            print(\'  건너뜀 : %s (%s)\' % (name, e))\n    return out\n\n\ndef run():\n    title(\'26. 제안서 PPT (미리 써 둔 내용을 회사 서식으로)\')\n    specs = load_specs()\n    if not specs:\n        print(\'제안서_내용 폴더에 json 이 없습니다.\')\n        print(\'위치 : %s\' % SPECS)\n        return\n    print(\'\')\n    print(\'만들 수 있는 제안서 %s건\' % won(len(specs)))\n    cur = \'\'\n    for i, (p, d) in enumerate(specs, 1):\n        g = d.get(\'요일\', \'\')\n        if g != cur:\n            cur = g\n            print(\'\')\n            print(\' -- %s --\' % (g or \'기타\'))\n        print(\' %2d. %s  (%d장)\' % (i, d.get(\'title\', \'?\'), len(d.get(\'slides\', []))))\n    print(\'\')\n    sel = ask(\'번호 (엔터=전부 만들기) > \')\n    pick = [specs[int(sel) - 1]] if sel.isdigit() and 1 <= int(sel) <= len(specs) else specs\n    site = ask(\'현장명 (엔터 = 현장명 없는 범용 표준본) > \').strip()\n    od = outdir(\'제안서PPT\')\n    mapping = {\'{{현장}}\': site if site else \'귀사\',\n               \'{{현장_제목}}\': (site + \' \') if site else \'\',\n               \'{{날짜}}\': today().strftime(\'%Y. %m. %d\')}\n    print(\'\')\n    made = 0\n    for p, d in pick:\n        d2 = fill(d, mapping)\n        base = \'%s_%s_%s_r1.pptx\' % (safe_name(site or \'표준\'),\n                                     safe_name(d2.get(\'파일명\', d2.get(\'title\', \'제안서\'))[:30]),\n                                     ymd6())\n        f = os.path.join(od, base)\n        try:\n            n = build(d2, f)\n            print(\'만듦 : %s  (%d장)\' % (f, n))\n            made += 1\n        except Exception as e:\n            print(\'실패 : %s  (%s)\' % (d2.get(\'title\'), e))\n    print(\'\')\n    print(\'%s건 완료. 대외 제출 전 반드시 한 번 열어 확인하십시오.\' % won(made))\n    log(\'제안서PPT\', \'%d건 %s\' % (made, site or \'범용\'))\n\n\nif __name__ == \'__main__\':\n    run(); pause()\n',
    'site_index.py': '# -*- coding: utf-8 -*-\n# 54판 v10 2026-09-27  (★제안서_PPT.py 가 이 줄의 v숫자로 새 판인지 가린다)\n"""site_index - 흩어진 결과를 「현장 하나당 한 곳」 으로 모아 보는 화면을 만든다. 토큰 0.\n\n왜 만들었나\n  프로님 2026-09-17 : "폴더가 여기 저기 흩어져 있는 것은 결과값 찾기가 힘드니\n  생성된 폴더는 몰아서 하나의 폴더에서 볼 수 있게 해. 산출, 견적, 실행, 회의록, 제안서, 단가장."\n\n무엇을 하지 않는가\n  ★ 파일을 옮기지 않는다. 폴더도 만들지 않는다. 이름도 바꾸지 않는다.\n  폴더는 프로님이 정하고 도구가 따라간다(km-00 10번). 그래서 「보는 화면」 만 더한다.\n  원본은 _도구결과\\\\{도구}\\\\{날짜}\\\\ 그대로 있고, 이 화면이 현장별로 묶어 링크만 건다.\n\n만드는 것\n  {base}\\\\_현장별_한곳에.html   더블클릭 -> 현장 카드. 파일을 누르면 그대로 열린다\n\n쓰는 법\n  단독 : python site_index.py\n  33번에 합치기 : t33_dashboard.py 안에서\n        import site_index\n        site_index.build()          # 현황판을 만들 때 같이 부른다\n"""\nimport os, io, re, glob, html, datetime, collections\n\ntry:\n    from common import cfg, outdir, today, ymd6, log\nexcept Exception:                      # 단독 실행 대비\n    def cfg(k):\n        d = {\'base\': r\'C:\\Users\\gamak\\OneDrive\\26년도 현장\\!!클로드가 저장하는 폴더\'}\n        d[\'out\'] = os.path.join(d[\'base\'], \'_도구결과\')\n        return d.get(k, \'\')\n    def today():\n        return datetime.date.today()\n    def log(*a):\n        pass\n\n# 도구 폴더 이름 -> 프로님이 부르시는 이름 (없으면 폴더 이름 그대로)\nKIND = collections.OrderedDict([\n    (\'도면수량\', \'산출\'), (\'객실수량표\', \'산출\'), (\'CB외함세트\', \'산출\'),\n    (\'견적서채우기\', \'견적\'), (\'증감비교\', \'견적\'), (\'단가붙이기\', \'실행\'),\n    (\'단가장채우기\', \'단가장\'), (\'단가장검진\', \'단가장\'),\n    (\'회의록\', \'회의록\'), (\'부서메일\', \'회의록\'),\n    (\'제안서초안\', \'제안서\'), (\'제안서PPT\', \'제안서\'), (\'자재사양서\', \'제안서\'),\n    (\'시방서치환\', \'제안서\'), (\'사진대지\', \'사진\'), (\'이미지PPT\', \'사진\'),\n    (\'납기역산\', \'일정\'), (\'수금레이더\', \'돈\'), (\'월말집계\', \'돈\'),\n    (\'의뢰서대장\', \'의뢰서\'), (\'완성품\', \'부탁서\'), (\'도면접수\', \'도면\'),\n])\nORDER = [\'산출\', \'견적\', \'실행\', \'단가장\', \'제안서\', \'회의록\', \'의뢰서\',\n         \'일정\', \'돈\', \'도면\', \'사진\', \'부탁서\', \'그 밖\']\n\nBAD = (\'_클로드에게\', \'_모르는기호\', \'_읽은파일\', \'_쪼개서맞춘것\', \'log\', \'.tmp\', \'~$\')\n\n\ndef kind_of(tool):\n    for k, v in KIND.items():\n        if k in tool:\n            return v\n    return \'그 밖\'\n\n\n# 도구가 파일 이름 앞에 붙이는 말 - 현장명이 아니다 (2026-09-27 미리보기에서 현장으로 잡혀 나옴)\nNOT_SITE = (\'메일\', \'보낼메일\', \'자가시험\', \'미확인회의록\', \'회의변경수량\', \'현황판\', \'아침한장\',\n            \'총괄점검\', \'회의록정리\', \'오늘할것\', \'답해주십시오\', \'어제있었던일\', \'할일추가\',\n            \'현장별\', \'발송로그\', \'아침대장\', \'소통이력\', \'확정\', \'앞으로할것\', \'찾아갈곳\')\nGENERIC = \'표준 (현장명 없는 범용본)\'\n\n\ndef site_of(fname, tool):\n    """파일 이름 앞머리에서 현장명을 뽑는다. 못 뽑으면 빈 값."""\n    base = os.path.splitext(fname)[0]\n    base = re.sub(r\'_?\\d{6}(_r\\d+)?$\', \'\', base)          # 뒤 날짜·판 제거\n    site = \'\'\n    for tag in (\'_도면수량\', \'_수량표\', \'_실행산출\', \'_견적서\', \'_제안서\', \'_증감\',\n                \'_사진대지\', \'_자재사양서\', \'_역산\', \'_초안\'):\n        if tag in base:\n            site = base.split(tag)[0].strip(\' _-\')\n            break\n    if not site:\n        parts = base.split(\'_\')\n        if len(parts) >= 2 and len(parts[0]) >= 2:\n            site = parts[0].strip(\' _-\')\n    site = re.sub(r\'[_ ]*\\d{6}$\', \'\', site).strip(\' _-\')     # 「앵커호텔_260927」 -> 「앵커호텔」\n    if site in NOT_SITE:\n        return \'\'\n    if site == \'표준\':\n        return GENERIC\n    return site\n\n\ndef _known_sites():\n    """도면 폴더의 현장 이름 (있으면). 이름 뒤쪽에 현장명이 붙은 파일을 찾는 데 쓴다."""\n    out = set()\n    try:\n        root = cfg(\'drawing\')\n    except Exception:\n        return out\n    for base in [root] + [os.path.join(root, d) for d in (os.listdir(root) if os.path.isdir(root) else [])\n                          if re.match(r\'^\\d{2,4}년?$\', d)]:\n        if not os.path.isdir(base):\n            continue\n        for d in os.listdir(base):\n            if os.path.isdir(os.path.join(base, d)) and not d.startswith((\'_\', \'~\')) \\\n                    and not re.match(r\'^\\d{2,4}년?$\', d):\n                out.add(d)\n    return out\n\n\ndef scan():\n    """_도구결과 아래를 훑어 {현장: {종류: [(파일명, 경로, 날짜)]}} 로 모은다."""\n    root = cfg(\'out\')\n    found = collections.defaultdict(lambda: collections.defaultdict(list))\n    loose = collections.defaultdict(list)\n    pending = []\n    if not root or not os.path.isdir(root):\n        return found, loose, root\n    for tool in sorted(os.listdir(root)):\n        tdir = os.path.join(root, tool)\n        if not os.path.isdir(tdir) or tool.startswith(\'_\'):\n            continue\n        kind = kind_of(tool)\n        for p in glob.glob(os.path.join(tdir, \'*\', \'*\')):\n            fn = os.path.basename(p)\n            if os.path.isdir(p) or any(b in fn for b in BAD):\n                continue\n            try:\n                mt = datetime.date.fromtimestamp(os.path.getmtime(p))\n            except Exception:\n                mt = None\n            site = site_of(fn, tool)\n            rec = (fn, p, mt, tool)\n            if site:\n                found[site][kind].append(rec)\n            else:\n                pending.append((kind, rec))\n    # 현장명이 앞에 없는 파일 (보낼메일_도면요청_연합기숙사.txt 등) - 아는 현장 이름이 들어 있으면 그 현장으로\n    known = set(k for k in found if k != GENERIC) | _known_sites()\n    for kind, rec in pending:\n        hit = [k for k in known if k and k in rec[0]]\n        if len(hit) == 1:\n            found[hit[0]][kind].append(rec)\n        else:\n            loose[kind].append(rec)\n    for site in found:\n        for kind in found[site]:\n            found[site][kind].sort(key=lambda r: (r[2] or datetime.date(1900, 1, 1)), reverse=True)\n    return found, loose, root\n\n\ndef _esc(s):\n    return html.escape(str(s))\n\n\ndef _url(p):\n    return \'file:///\' + p.replace(\'\\\\\', \'/\').replace(\' \', \'%20\')\n\n\nCSS = """\n:root{--bg:#F2F4F7;--card:#fff;--ink:#18212E;--ink2:#43505F;--muted:#77838F;\n --line:#DCE1E8;--navy:#1F3864;--blue:#2E74B5;--sky:#E7EEF7;--warn:#C77B2B}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font-size:14px;line-height:1.55;\n font-family:"맑은 고딕","Malgun Gothic",sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:22px 18px 60px}\nh1{font-size:23px;margin:0 0 4px;letter-spacing:-.02em}\n.sub{color:var(--muted);font-size:13px;margin-bottom:18px}\n.tools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}\n.tools input{flex:1 1 260px;padding:9px 12px;border:1px solid var(--line);border-radius:4px;font-size:14px}\n.site{background:var(--card);border:1px solid var(--line);border-radius:5px;margin-bottom:12px;overflow:hidden}\n.site>summary{cursor:pointer;padding:12px 16px;font-weight:700;font-size:15px;\n display:flex;gap:10px;align-items:center;list-style:none;background:var(--card)}\n.site>summary::-webkit-details-marker{display:none}\n.site[open]>summary{border-bottom:1px solid var(--line);background:var(--sky)}\n.cnt{margin-left:auto;font-weight:400;font-size:12px;color:var(--muted)}\n.body{padding:6px 16px 14px}\n.kind{margin-top:10px}\n.kind h3{font-size:12px;letter-spacing:.06em;color:var(--navy);margin:0 0 5px;\n border-left:3px solid var(--blue);padding-left:7px}\n.f{display:flex;gap:10px;padding:5px 0 5px 10px;border-bottom:1px dotted var(--line);font-size:13px}\n.f:last-child{border-bottom:0}\n.f a{color:var(--ink2);text-decoration:none;flex:1;word-break:break-all}\n.f a:hover{color:var(--blue);text-decoration:underline}\n.f .d{color:var(--muted);font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.f .t{color:var(--muted);font-size:11px;white-space:nowrap}\n.note{background:#FAF0E2;border:1px solid var(--warn);border-radius:5px;padding:12px 15px;\n font-size:13px;color:var(--ink2);margin-top:20px}\n.note b{color:var(--warn)}\n.empty{color:var(--muted);padding:24px;text-align:center;background:var(--card);\n border:1px dashed var(--line);border-radius:5px}\n"""\n\nJS = """\nfunction kmFilter(v){\n  v=(v||\'\').trim().toLowerCase();\n  document.querySelectorAll(\'.site\').forEach(function(d){\n    var hit = !v || d.dataset.k.indexOf(v)>=0;\n    d.style.display = hit?\'\':\'none\';\n    if(v && hit) d.open = true;\n  });\n}\n"""\n\n\ndef render(found, loose, root):\n    out = [\'<!doctype html><meta charset="utf-8">\',\n           \'<title>현장별 한 곳에</title><style>%s</style>\' % CSS,\n           \'<div class="wrap">\',\n           \'<h1>현장별 한 곳에</h1>\',\n           \'<div class="sub">%s 기준 · 결과 원본은 %s 안에 그대로 있습니다. \'\n           \'이 화면은 현장별로 묶어 보여줄 뿐 파일을 옮기지 않습니다.</div>\'\n           % (_esc(today().strftime(\'%Y-%m-%d\')), _esc(root or \'(폴더를 못 찾음)\')),\n           \'<div class="tools"><input id="q" placeholder="현장 이름을 치면 걸러집니다" \'\n           \'oninput="kmFilter(this.value)"></div>\']\n    if not found and not loose:\n        out.append(\'<div class="empty">아직 결과가 없습니다. 도구를 한 번 돌리시면 여기에 쌓입니다.</div>\')\n    for site in sorted(found):\n        kinds = found[site]\n        total = sum(len(v) for v in kinds.values())\n        keys = [k for k in ORDER if k in kinds] + [k for k in kinds if k not in ORDER]\n        out.append(\'<details class="site" data-k="%s"><summary>%s\'\n                   \'<span class="cnt">%s · 파일 %d개</span></summary><div class="body">\'\n                   % (_esc(site.lower()), _esc(site),\n                      _esc(\' · \'.join(keys)), total))\n        for k in keys:\n            out.append(\'<div class="kind"><h3>%s</h3>\' % _esc(k))\n            for fn, p, mt, tool in kinds[k][:12]:\n                out.append(\'<div class="f"><a href="%s">%s</a>\'\n                           \'<span class="t">%s</span><span class="d">%s</span></div>\'\n                           % (_url(p), _esc(fn), _esc(tool),\n                              _esc(mt.strftime(\'%m-%d\') if mt else \'\')))\n            if len(kinds[k]) > 12:\n                out.append(\'<div class="f"><a>… 그 밖 %d개</a></div>\' % (len(kinds[k]) - 12))\n            out.append(\'</div>\')\n        out.append(\'</div></details>\')\n    if loose:\n        n = sum(len(v) for v in loose.values())\n        out.append(\'<details class="site" data-k="현장미상"><summary>현장을 못 읽은 파일\'\n                   \'<span class="cnt">파일 %d개</span></summary><div class="body">\' % n)\n        for k in sorted(loose):\n            out.append(\'<div class="kind"><h3>%s</h3>\' % _esc(k))\n            for fn, p, mt, tool in loose[k][:10]:\n                out.append(\'<div class="f"><a href="%s">%s</a><span class="t">%s</span></div>\'\n                           % (_url(p), _esc(fn), _esc(tool)))\n            out.append(\'</div>\')\n        out.append(\'</div></details>\')\n    out.append(\'<div class="note"><b>파일은 움직이지 않았습니다.</b> \'\n               \'원본은 도구별 폴더에 그대로 있고, 이 화면이 현장 이름으로 묶어 링크만 겁니다. \'\n               \'현장 이름은 파일 이름 앞머리에서 읽습니다 — 「현장을 못 읽은 파일」에 들어간 것은 \'\n               \'파일 이름이 현장명으로 시작하지 않는 것입니다.</div>\')\n    out.append(\'</div><script>%s</script>\' % JS)\n    return \'\\n\'.join(out)\n\n\ndef build(quiet=False):\n    found, loose, root = scan()\n    doc = render(found, loose, root)\n    base = cfg(\'base\')\n    path = os.path.join(base, \'_현장별_한곳에.html\') if base else \'_현장별_한곳에.html\'\n    try:\n        io.open(path, \'w\', encoding=\'utf-8\').write(doc)\n    except Exception as e:\n        path = \'_현장별_한곳에.html\'\n        io.open(path, \'w\', encoding=\'utf-8\').write(doc)\n        if not quiet:\n            print(\'기본 위치에 못 써서 현재 폴더에 만들었습니다 : %s\' % e)\n    if not quiet:\n        print(\'현장 %d곳 · 파일 %d개\'\n              % (len(found), sum(len(v) for s in found.values() for v in s.values())))\n        print(\'만듦 : %s\' % path)\n    try:\n        log(\'현장별한곳에\', \'현장 %d곳\' % len(found))\n    except Exception:\n        pass\n    return path\n\n\nif __name__ == \'__main__\':\n    build()\n',
    'errata_apply.py': '# -*- coding: utf-8 -*-\n# 54판 v10 2026-09-27  (★제안서_PPT.py 가 이 줄의 v숫자로 새 판인지 가린다)\n"""errata_apply - 회사 제안서 pptx 의 5성급 점유율을 「해외스펙 제외 80% 이상」 으로 통일한다. 토큰 0.\n\n왜 만들었나\n  청담PJ 제안서(260715)에 5성급 점유율이 70% · 70%+ · 75% · 80% 로 섞여 있었다.\n  프로님이 2026-09-17 「해외스펙 제외 80% 이상」 으로 확정하셨다.\n  pptx 원본이 들어오는 순간 손 없이 고치려고 만들었다.\n\n지키는 것\n  ★ 원본을 덮어쓰지 않는다. 같은 폴더에 「_점유율80」 을 붙인 새 파일로 낸다.\n  ★ 점유율 문장만 건드린다. 「점유」 「5성급」 이 있는 문단 안의 70% · 75% 만 80% 로 바꾼다.\n     다른 숫자(6시간, 40년, 52개 호텔 …)는 절대 안 건드린다.\n  ★ 바꾼 곳을 하나도 빠짐없이 화면과 _점유율80_바꾼곳.csv 에 남긴다.\n\n쓰는 법\n  python errata_apply.py "원본.pptx"\n  또는 인수 없이 누르면 원틀\\\\제안서 폴더의 pptx 를 골라 준다.\n"""\nimport os, re, sys, io, csv\n\nfrom pptx import Presentation\n\nPCT = re.compile(r\'7[05]\\s*%\')          # 70% · 75% (70%+ 도 여기서 걸린다)\nNEED = (\'점유\', \'5성급\', \'5 성급\', \'10곳\')  # 이 말이 든 문단만 본다\nSCOPE = \'(해외스펙 제외)\'\n\n\ndef _paras(prs):\n    for si, slide in enumerate(prs.slides, 1):\n        for sh in slide.shapes:\n            frames = []\n            if sh.has_text_frame:\n                frames.append(sh.text_frame)\n            if getattr(sh, \'has_table\', False) and sh.has_table:\n                for row in sh.table.rows:\n                    for c in row.cells:\n                        frames.append(c.text_frame)\n            for tf in frames:\n                for p in tf.paragraphs:\n                    yield si, p\n\n\nALONE = re.compile(r\'^\\s*7[05]\\s*%\\s*\\+?\\s*$\')          # 「70%+」 처럼 숫자만 있는 큰 글씨\nWITH_TAIL = re.compile(r\'7[05](\\s*)%((?:\\s*이상)?(?:\\s*(?:점유|설치))?)\')\n\n\ndef fix(src, dst=None):\n    prs = Presentation(src)\n    log = []\n    # 장마다 「점유」 가 있는지 먼저 본다 - 숫자만 있는 큰 글씨는 이걸로 판단한다\n    share_slides = set()\n    for si, p in _paras(prs):\n        if \'점유\' in \'\'.join(r.text for r in p.runs):\n            share_slides.add(si)\n    for si, p in _paras(prs):\n        text = \'\'.join(r.text for r in p.runs)\n        if not text:\n            continue\n        # ① 숫자만 있는 큰 글씨 (「70%+」) - 같은 장에 「점유」 가 있을 때만\n        if ALONE.match(text) and si in share_slides:\n            for r in p.runs:\n                if PCT.search(r.text):\n                    before = r.text\n                    r.text = PCT.sub(\'80%\', r.text)\n                    log.append([si, before, r.text])\n            continue\n        # ② 점유율 설명 글귀 (숫자 없음) - 기준을 붙인다\n        if \'점유율\' in text and not PCT.search(text) and \'해외\' not in text and p.runs:\n            last = p.runs[-1]\n            before = text\n            last.text = last.text.rstrip() + \' \' + SCOPE\n            log.append([si, before, \'\'.join(r.text for r in p.runs)])\n            continue\n        # ③ 점유율 문장 - 숫자를 80 으로, 기준이 없으면 숫자 바로 뒤에 붙인다\n        if not any(k in text for k in NEED) or not PCT.search(text):\n            continue\n        has_scope = \'해외\' in text\n        for r in p.runs:\n            if PCT.search(r.text):\n                before = r.text\n                if has_scope:\n                    r.text = PCT.sub(\'80%\', r.text)\n                else:\n                    r.text = WITH_TAIL.sub(lambda m: \'80\' + m.group(1) + \'%\' + m.group(2) + \' \' + SCOPE,\n                                           r.text, count=1)\n                    r.text = PCT.sub(\'80%\', r.text)\n                    has_scope = True\n                log.append([si, before, r.text])\n    if dst is None:\n        base, ext = os.path.splitext(src)\n        dst = base + \'_점유율80\' + ext\n    prs.save(dst)\n    with io.open(os.path.splitext(dst)[0] + \'_바꾼곳.csv\', \'w\', encoding=\'utf-8-sig\', newline=\'\') as f:\n        w = csv.writer(f)\n        w.writerow([\'장\', \'전\', \'후\'])\n        w.writerows(log)\n    return dst, log\n\n\ndef run(path=None):\n    if not path:\n        try:\n            from t54_deck import find_sources\n            srcs = [s for s in find_sources() if \'_점유율80\' not in s]\n        except Exception:\n            srcs = []\n        if not srcs:\n            print(\'고칠 pptx 를 못 찾았습니다. 3_공통사용\\\\원틀\\\\제안서\\\\ 에 넣어 주십시오.\')\n            return\n        for i, s in enumerate(srcs, 1):\n            print(\' %2d. %s\' % (i, os.path.basename(s)))\n        sel = input(\'번호 > \').strip()\n        if not sel.isdigit() or not (1 <= int(sel) <= len(srcs)):\n            return\n        path = srcs[int(sel) - 1]\n    dst, log = fix(path)\n    print(\'\')\n    print(\'바꾼 곳 %d군데\' % len(log))\n    for si, a, b in log:\n        print(\'  %2d장 : %s  ->  %s\' % (si, a, b))\n    print(\'\')\n    print(\'새 파일 : %s\' % dst)\n    print(\'원본은 그대로 있습니다.\')\n\n\nif __name__ == \'__main__\':\n    run(sys.argv[1] if len(sys.argv) > 1 else None)\n',
    'deck_check.py': '# -*- coding: utf-8 -*-\n# 54판 v10 2026-09-27  (★제안서_PPT.py 가 이 줄의 v숫자로 새 판인지 가린다)\n"""deck_check - 만든 제안서 pptx 의 글자 넘침·겹침·붙음·표 밀림을 잰다. 토큰 0. 메뉴 번호 없음(부품).\n\n왜 만들었나\n  2026-09-27 미리보기에서 사람 눈으로 찾은 결함(도어락 구성도 선 위 글자 겹침, 평면 마킹 「현관」 이\n  표시 상자에 붙음)을 PC 에서 뽑을 때마다 기계가 먼저 찾게 하려고. 프로님 : "검사기 pc에도 넣어"\n\n어떻게 재나\n  브라우저 없이, python-pptx 가 이미 쓰는 Pillow 로 **실제 글꼴(맑은 고딕) 폭**을 재서\n  줄바꿈을 계산한다. 그 결과로 글자가 차지하는 자리를 구해 서로 겹치는지 본다.\n  PC 에 맑은 고딕이 없으면 비슷한 한글 글꼴로 재고, 어느 글꼴로 쟀는지 결과에 적는다.\n\n재는 것\n  넘침      글자가 제 상자보다 길다 (아래로 흘러넘침)\n  겹침      서로 다른 두 글자 덩어리가 겹친다\n  붙음      글자가 다른 색칠 도형에 걸치거나 3pt 안으로 붙는다 (그 도형 안에 든 글자는 제외)\n  표 밀림   표 칸 글자가 줄바꿈되어 표가 바닥글(5.15in)까지 내려온다\n  장 밖     글자가 장 아래로 나간다\n\n회사 원본에서 복사한 장(사진·그룹·자리표시자가 있는 장)은 서식을 모르므로 건너뛰고 몇 장인지만 적는다.\n\n쓰는 법\n  import deck_check; probs, note = deck_check.check(\'제안서.pptx\')\n  python deck_check.py 파일.pptx [폴더 ...]\n"""\nimport os, sys, glob\n\nfrom pptx import Presentation\nfrom pptx.util import Emu\nfrom pptx.enum.shapes import MSO_SHAPE_TYPE\n\nEMU_IN = 914400.0\nFOOTER_Y = 5.15          # 바닥글(5.22in) 바로 위\nTOUCH = 3 / 72.0         # 3pt 안으로 붙으면 「붙음」\n\n_FONT_CANDS = {\n    False: [r\'C:\\Windows\\Fonts\\malgun.ttf\', \'/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc\',\n            \'/usr/share/fonts/truetype/nanum/NanumGothic.ttf\'],\n    True: [r\'C:\\Windows\\Fonts\\malgunbd.ttf\', \'/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc\',\n           \'/usr/share/fonts/truetype/nanum/NanumGothicBold.ttf\'],\n}\n_cache = {}\nFONT_USED = \'\'\n\n\ndef _font(bold):\n    """기준 100px 크기의 글꼴. 폭은 크기에 비례하므로 한 번만 연다."""\n    global FONT_USED\n    if bold in _cache:\n        return _cache[bold]\n    from PIL import ImageFont\n    f = None\n    for p in _FONT_CANDS[bold]:\n        if os.path.exists(p):\n            try:\n                f = ImageFont.truetype(p, 100)\n                FONT_USED = FONT_USED or os.path.basename(p)\n                break\n            except Exception:\n                continue\n    if f is None:                                   # 글꼴이 하나도 없으면 한글 한 자 = 1em 로 어림\n        f = False\n        FONT_USED = FONT_USED or \'(글꼴 없음 - 어림)\'\n    _cache[bold] = f\n    return f\n\n\ndef _w(text, size_pt, bold):\n    """글자 폭 (인치)"""\n    f = _font(bold)\n    if not f:\n        return sum((1.0 if ord(c) > 0x2E80 else 0.55) for c in text) * size_pt / 72.0\n    return f.getlength(text) * size_pt / 100.0 / 72.0\n\n\ndef _lh(size_pt, bold):\n    """한 줄 높이 (인치). 글꼴마다 위·아래 여백이 달라(맑은 고딕 ≈1.3, Noto ≈1.45)\n    글꼴에서 읽지 않고 1.25 배로 고정한다 - 미리보기(렌더 검수)와 같은 값."""\n    return size_pt * 1.25 / 72.0\n\n\ndef _wrap(text, width, size, bold):\n    """어절(띄어쓰기) 단위로 줄을 나눈다. 한 어절이 폭보다 길면 글자 단위로 자른다.\n    돌려주는 것 : 줄마다의 폭 목록"""\n    out = []\n    for para in text.split(\'\\n\'):\n        words = para.split(\' \')\n        cur = \'\'\n        for wd in words:\n            cand = wd if not cur else cur + \' \' + wd\n            if _w(cand, size, bold) <= width + 1e-6 or not cur:\n                if _w(cand, size, bold) > width + 1e-6 and not cur:\n                    # 어절 하나가 폭보다 길다 -> 글자 단위\n                    piece = \'\'\n                    for ch in wd:\n                        if _w(piece + ch, size, bold) > width + 1e-6 and piece:\n                            out.append(_w(piece, size, bold))\n                            piece = ch\n                        else:\n                            piece += ch\n                    cur = piece\n                else:\n                    cur = cand\n            else:\n                out.append(_w(cur, size, bold))\n                cur = wd\n        out.append(_w(cur, size, bold))\n    return out\n\n\ndef _runs_info(tf):\n    """문단마다 (글자, 크기pt, 굵기, 정렬, 문단 뒤 간격pt)"""\n    paras = []\n    for p in tf.paragraphs:\n        txt = \'\'.join(r.text for r in p.runs)\n        size, bold = 11.0, False\n        for r in p.runs:\n            if r.font.size:\n                size = r.font.size.pt\n            if r.font.bold:\n                bold = True\n        sa = p.space_after.pt if p.space_after is not None else 0.0\n        paras.append((txt, size, bold, str(p.alignment or \'\'), sa))\n    return paras\n\n\ndef _text_extent(sh):\n    """글상자 안 글자가 실제로 차지하는 자리 (x1, y1, x2, y2) 인치, 그리고 필요한 높이"""\n    tf = sh.text_frame\n    x, y = sh.left / EMU_IN, sh.top / EMU_IN\n    w, h = sh.width / EMU_IN, sh.height / EMU_IN\n    ml = (tf.margin_left if tf.margin_left is not None else Emu(91440)) / EMU_IN\n    mr = (tf.margin_right if tf.margin_right is not None else Emu(91440)) / EMU_IN\n    mt = (tf.margin_top if tf.margin_top is not None else Emu(45720)) / EMU_IN\n    mb = (tf.margin_bottom if tf.margin_bottom is not None else Emu(45720)) / EMU_IN\n    iw = max(0.05, w - ml - mr)\n    total, widest, left_most, right_most = 0.0, 0.0, None, None\n    paras = _runs_info(tf)\n    for i, (txt, size, bold, al, sa) in enumerate(paras):\n        widths = _wrap(txt, iw, size, bold) if tf.word_wrap is not False else [_w(txt, size, bold)]\n        total += len(widths) * _lh(size, bold) + (sa / 72.0 if i < len(paras) - 1 else 0)\n        for lw in widths:\n            if not txt.strip():\n                continue\n            if \'CENTER\' in al:\n                lx = x + ml + (iw - lw) / 2\n            elif \'RIGHT\' in al:\n                lx = x + ml + iw - lw\n            else:\n                lx = x + ml\n            left_most = lx if left_most is None else min(left_most, lx)\n            right_most = lx + lw if right_most is None else max(right_most, lx + lw)\n    if left_most is None:\n        return None, 0\n    anchor = str(tf.vertical_anchor or \'\')\n    ih = h - mt - mb\n    if \'MIDDLE\' in anchor:\n        ty = y + mt + (ih - total) / 2\n    elif \'BOTTOM\' in anchor:\n        ty = y + mt + ih - total\n    else:\n        ty = y + mt\n    # 첫 줄 위쪽 여백(글꼴 위 공간)만큼 실제 글자는 조금 아래 - 겹침 판정은 가운데 80% 로 본다\n    return (left_most, ty, right_most, ty + total), total + mt + mb\n\n\ndef _box(sh):\n    return (sh.left / EMU_IN, sh.top / EMU_IN, (sh.left + sh.width) / EMU_IN, (sh.top + sh.height) / EMU_IN)\n\n\ndef _filled(sh):\n    try:\n        return sh.fill.type == 1\n    except Exception:\n        return False\n\n\ndef _inter(a, b):\n    return min(a[2], b[2]) - max(a[0], b[0]), min(a[3], b[3]) - max(a[1], b[1])\n\n\ndef _is_copied(slide):\n    """회사 원본에서 복사해 온 장인가 (사진·그룹·자리표시자·차트가 있으면)"""\n    for sh in slide.shapes:\n        t = sh.shape_type\n        if t in (MSO_SHAPE_TYPE.PICTURE, MSO_SHAPE_TYPE.GROUP, MSO_SHAPE_TYPE.PLACEHOLDER,\n                 MSO_SHAPE_TYPE.CHART) or getattr(sh, \'is_placeholder\', False):\n            return True\n    return False\n\n\ndef _table_bottom(sh):\n    """표는 칸 글자가 줄바꿈되면 줄이 스스로 늘어난다 -> 실제 바닥"""\n    tbl = sh.table\n    y = sh.top / EMU_IN\n    for r in tbl.rows:\n        need = r.height / EMU_IN\n        for ci, c in enumerate(r.cells):\n            cw = tbl.columns[ci].width / EMU_IN\n            ml = (c.margin_left or Emu(91440)) / EMU_IN\n            mr = (c.margin_right or Emu(91440)) / EMU_IN\n            mt = (c.margin_top or Emu(45720)) / EMU_IN\n            mb = (c.margin_bottom or Emu(45720)) / EMU_IN\n            hh = 0.0\n            for txt, size, bold, al, sa in _runs_info(c.text_frame):\n                hh += len(_wrap(txt, max(0.05, cw - ml - mr), size, bold)) * _lh(size, bold) + sa / 72.0\n            need = max(need, hh + mt + mb)\n        y += need\n    return y\n\n\ndef check(path, skip_copied=True):\n    """돌려주는 것 : ([(장, 종류, 설명)], 메모)"""\n    prs = Presentation(path)\n    sh_h = prs.slide_height / EMU_IN\n    probs, skipped = [], 0\n    for si, slide in enumerate(prs.slides, 1):\n        if skip_copied and _is_copied(slide):\n            skipped += 1\n            continue\n        texts, fills = [], []\n        for sh in slide.shapes:\n            if getattr(sh, \'has_table\', False) and sh.has_table:\n                bot = _table_bottom(sh)\n                if bot > FOOTER_Y + 0.02:\n                    probs.append((si, \'표 밀림\', \'표가 바닥글까지 내려옴 (%.2fin 넘침)\' % (bot - FOOTER_Y)))\n                continue\n            if _filled(sh):\n                fills.append((sh.shape_id, _box(sh)))\n            if not sh.has_text_frame or not sh.text_frame.text.strip():\n                continue\n            ext, need = _text_extent(sh)\n            if not ext:\n                continue\n            label = sh.text_frame.text.strip().replace(\'\\n\', \' \')[:18]\n            over = need - sh.height / EMU_IN\n            if over > 0.06:\n                probs.append((si, \'넘침\', \'「%s」 상자보다 %.2fin 김\' % (label, over)))\n            if ext[3] > sh_h + 0.01:\n                probs.append((si, \'장 밖\', \'「%s」 장 아래로 나감\' % label))\n            texts.append((sh.shape_id, ext, _box(sh), label))\n        # 겹침 (글자끼리)\n        for i in range(len(texts)):\n            for j in range(i + 1, len(texts)):\n                ox, oy = _inter(texts[i][1], texts[j][1])\n                if ox > 0.03 and oy > 0.03:\n                    probs.append((si, \'겹침\', \'「%s」 / 「%s」\' % (texts[i][3], texts[j][3])))\n        # 붙음 (글자가 다른 색칠 도형에 걸치거나 바로 옆)\n        for tid, ext, tbox, label in texts:\n            for fid, fb in fills:\n                if fid == tid:\n                    continue\n                if ext[0] >= fb[0] - 0.005 and ext[2] <= fb[2] + 0.005 and ext[1] >= fb[1] - 0.005 and ext[3] <= fb[3] + 0.005:\n                    continue                                   # 그 도형 안에 든 글자\n                ox, oy = _inter(ext, fb)\n                if oy > 0.02 and ox > -TOUCH:\n                    probs.append((si, \'붙음\', \'「%s」 가 다른 도형에 걸침/붙음\' % label))\n                    break\n    note = \'글꼴 %s 로 잼\' % FONT_USED\n    if skipped:\n        note += \' · 회사 원본 장 %d장은 건너뜀\' % skipped\n    return probs, note\n\n\ndef report(path, quiet_ok=False):\n    """화면에 한 줄(이상 없음) 또는 문제 목록을 찍는다. 문제 수를 돌려준다."""\n    try:\n        probs, note = check(path)\n    except Exception as e:\n        print(\'  점검 : 못 함 (%s)\' % e)\n        return -1\n    if not probs:\n        if not quiet_ok:\n            print(\'  점검 : 이상 없음  (%s)\' % note)\n        return 0\n    print(\'  점검 : 확인할 곳 %d군데  (%s)\' % (len(probs), note))\n    for si, kind, msg in probs:\n        print(\'     %2d장 %-4s %s\' % (si, kind, msg))\n    return len(probs)\n\n\ndef run(paths=None):\n    """★제안서_PPT.py 4번 : 최근 만든 제안서 폴더를 통째로 점검"""\n    if not paths:\n        try:\n            from common import cfg\n            root = os.path.join(cfg(\'out\'), \'제안서PPT\')\n        except Exception:\n            root = \'\'\n        days = sorted(glob.glob(os.path.join(root, \'*\'))) if root else []\n        if not days:\n            print(\'점검할 제안서가 없습니다. 먼저 1번으로 만드십시오.\')\n            return\n        paths = sorted(glob.glob(os.path.join(days[-1], \'*.pptx\')))\n        print(\'점검 폴더 : %s  (%d개)\' % (days[-1], len(paths)))\n    total = 0\n    for p in paths:\n        if os.path.basename(p).startswith(\'~$\'):\n            continue\n        print(os.path.basename(p))\n        n = report(p)\n        total += max(0, n)\n    print(\'\')\n    print(\'확인할 곳 합계 %d군데\' % total if total else \'전부 이상 없음\')\n    if total:\n        print(\'→ 위 장 번호를 파워포인트에서 열어 보시고, 이상하면 그 목록을 클로드에게 보여 주십시오.\')\n\n\nif __name__ == \'__main__\':\n    args = sys.argv[1:]\n    ps = []\n    for a in args:\n        ps += sorted(glob.glob(os.path.join(a, \'*.pptx\'))) if os.path.isdir(a) else [a]\n    run(ps or None)\n',
}
